<?php
/*
 * FICHIER : Ajoutecategorie.php
 * RÔLE    : créer, modifier et supprimer les catégories.
 * La suppression peut conserver ou supprimer les articles associés.
 */
require __DIR__.'/connexion.php';require_auth();$editing=null;
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['idcategorie']??null,FILTER_VALIDATE_INT);
 if($action==='delete'&&$id){$mode=(string)($_POST['delete_mode']??'category');if($mode==='category_articles'){$bd->prepare('DELETE FROM articles WHERE idcategorie=?')->execute([$id]);}$bd->prepare('DELETE FROM categories WHERE idcategorie=?')->execute([$id]);flash($mode==='category_articles'?'Catégorie et articles associés supprimés.':'Catégorie supprimée. Les articles associés sont conservés.');header('Location: Ajoutecategorie.php');exit;}
 if($action==='save'){$name=trim((string)($_POST['categorie']??''));if($name===''){flash('Le nom de catégorie est obligatoire.','error');}else{if($id){$s=$bd->prepare('UPDATE categories SET categorie=? WHERE idcategorie=?');$s->execute([$name,$id]);}else{$s=$bd->prepare('INSERT INTO categories(categorie) VALUES(?)');$s->execute([$name]);}flash($id?'Catégorie modifiée.':'Catégorie créée.');header('Location: Ajoutecategorie.php');exit;}}
 if($action==='edit'&&$id){$s=$bd->prepare('SELECT * FROM categories WHERE idcategorie=?');$s->execute([$id]);$editing=$s->fetch();}}
$rows=$bd->query('SELECT idcategorie,categorie FROM categories ORDER BY categorie')->fetchAll();page_start('Catégories','categories');
?><div class="eyebrow">Catalogue / Organisation</div><div class="heading-row"><div><h1>Catégories</h1><p>Structurez les produits de votre boutique.</p></div><span class="btn btn-quiet"><?=count($rows)?> catégories</span></div><section class="panel form-panel"><div class="panel-head" style="padding:0 0 17px;margin-bottom:18px"><h2><?=$editing?'Modifier la catégorie':'Nouvelle catégorie'?></h2></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="idcategorie" value="<?=(int)($editing['idcategorie']??0)?>"><div class="field"><label for="categorie">Nom de catégorie</label><input id="categorie" name="categorie" maxlength="250" required value="<?=e($editing['categorie']??'')?>" placeholder="Ex. Produits frais"></div><div class="form-actions"><button class="btn btn-primary" type="submit"><?=$editing?'Enregistrer les changements':'＋ Ajouter la catégorie'?></button><?php if($editing):?><a class="btn btn-quiet" href="Ajoutecategorie.php">Annuler</a><?php endif?></div></form></section><section class="panel"><div class="panel-head"><h2>Catégories enregistrées</h2><small>Modification et suppression</small></div><?php if(!$rows):?><div class="empty">Aucune catégorie à afficher.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Catégorie</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['categorie'])?></b></td><td><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="edit"><input type="hidden" name="idcategorie" value="<?=(int)$r['idcategorie']?>"><button class="btn btn-quiet">Modifier</button></form><form method="post" onsubmit="return chooseCategoryDelete(this)"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="delete_mode" value="category"><input type="hidden" name="idcategorie" value="<?=(int)$r['idcategorie']?>"><button class="btn btn-danger">Supprimer</button></form></div></td></tr><?php endforeach?></tbody></table></div><?php endif?></section><script>function chooseCategoryDelete(form){if(!confirm('Supprimer uniquement la catégorie ? Les articles seront conservés.')){if(!confirm('Supprimer la catégorie ET tous les articles qui lui sont attribués ? Cette action est définitive.'))return false;form.delete_mode.value='category_articles';}return true;}</script><?php page_end();
